/** Distinct authors of comments that have not been soft-deleted. Order is unspecified. */
export async function listCommentAuthorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ authorId: comments.authorId })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        isNull(comments.archivedAt),
      ),
    )
    .groupBy(comments.authorId)
    .all();

  return rows.map((row) => brandId<UserId>(row.authorId));
}

export async function countComments(

  return commentRepo.listThread(orgId, issueId);
}

/**
 * People shown on the issue's participants strip: the author, the current
 * assignee, and authors of comments that have not been deleted. Removed
 * members are dropped even when they wrote the issue.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const commentAuthors = await commentRepo.listCommentAuthorIds(orgId, issueId);
  const candidates = new Set<UserId>([
    issue.authorId,
    ...commentAuthors,
    ...(issue.assigneeId === null ? [] : [issue.assigneeId]),
  ]);

  const active: UserId[] = [];
  for (const userId of candidates) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member?.status === "active") active.push(userId);
  }
  return active;
}

